import { FunctionalComponent } from 'preact';
import { Suspense, lazy } from 'preact/compat';
import { useDispatch, useSelector } from 'react-redux';
import { useEffect } from 'preact/hooks';

import { selectFriendsData, selectReadNotReceivedMessages } from './slice/selectors';
import { sawMessage } from './slice/thunks';

import Header from './components/Header';

import styles from './styles.module.scss';
import useHasBookmarks from '../user/bookmarksBar/useHasBookmarksBar';

const List = lazy(() => import('./components/List'));

const FriendsContent: FunctionalComponent = () => {
  const dispatch = useDispatch();
  const friends = useSelector(selectFriendsData);
  const readFriendMessages = useSelector(selectReadNotReceivedMessages);
  const hasBookmarks = useHasBookmarks();

  useEffect(() => {
    readFriendMessages.forEach((message) => {
      dispatch(sawMessage(message));
    });
  }, []);

  return (
    <div className={styles.friendsContainer} style={{ top: hasBookmarks ? '70px' : 'calc(70px + 46px)' }}>
      <Header />
      {!!friends.length && (
        <Suspense fallback={null}>
          <List />
        </Suspense>
      )}
    </div>
  );
};

export default FriendsContent;
